import{z as n,x as i,o as r,c as d,q as o,j as B,D as e,d as s,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"KDF 与慢哈希","description":"","frontmatter":{"title":"KDF 与慢哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kdf-slow-hash.md","filePath":"cs/kdf-slow-hash.md","lastUpdated":1791413859000}'),D={name:"cs/kdf-slow-hash.md"};function p(h,a,F,m,C,f){const t=i("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="kdf-与慢哈希" tabindex="-1">KDF 与慢哈希 <a class="header-anchor" href="#kdf-与慢哈希" aria-label="Permalink to &quot;KDF 与慢哈希&quot;">​</a></h1><div class="epigraph"><p>从口令派生密钥必须贵而带盐；普通哈希太快，离线猜测会把低熵秘密一次试完。</p><footer>—— 据 PKCS #5 / PBKDF2；Morris and Thompson 对照；Anderson 对慢哈希的整理</footer></div><p><a href="/cs/password-salt">上一课</a>规定库里不存原文、要加盐。本课不重讲「盐打破彩虹表」。缺口是速度：SHA 一类摘要按设计很快，这对本课<a href="/cs/hash-collision">哈希碰撞</a> 的完整性用途是优点，对口令是缺点。KDF 与专门慢哈希把猜测变成算力与内存预算。认证协议下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>口令课留下慢哈希一词。密钥派生函数（KDF）还有另一用途：从 DH 共享秘密拉出 AEAD 键（HKDF），那要快而均匀。口令 KDF 相反：故意慢、可调迭代、最好抗大规模并行。缺口是<strong>两种 KDF 不要用错场合</strong>。</p><p><span class="marginnote">术语翻译：盐是存进库里、每个用户不同的一段随机数。它的作用是让「同口令的两个人」哈希值也不同，逼攻击者对每个用户分别重算，而不是算一次比对全库。</span></p><p><span class="marginnote">参数（迭代、内存）随硬件涨。本课不点具体口令破解配置。防御是用为口令设计的函数，并保护哈希库本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>口令：盐 + 慢 KDF，存派生结果。会话：HKDF 从高熵秘密派生，不套用口令参数。升级：算法标识与参数要和哈希一起存，才能迁函数。本课不比较全部函数商品名当选购广告。</p>',9)),(r(),B(A,null,{default:e(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PW%5B%22%E4%BD%8E%E7%86%B5%E5%8F%A3%E4%BB%A4%22%5D%20--%3E%20SLOW%5B%22%E6%85%A2%20KDF%20%E5%8A%A0%E7%9B%90%22%5D%0A%20%20SS%5B%22%E9%AB%98%E7%86%B5%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%20--%3E%20HKDF%5B%22%E5%BF%AB%E9%80%9F%20HKDF%22%5D%0A%20%20SLOW%20--%3E%20STORE%5B%22%E5%AD%98%E5%82%A8%E6%B4%BE%E7%94%9F%E5%80%BC%22%5D%0A%20%20HKDF%20--%3E%20AEAD%5B%22%E4%BC%9A%E8%AF%9D%E9%94%AE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[s("慢哈希改变的是威胁模型里「抄库之后」的代价，不防止在线猜——在线要靠认证协议的限速与锁定。HKDF 服务"),E("a",{href:"/cs/dh-vs-rsa"},"DH 分工"),s(" 已得到的秘密。两者都不是加密算法本身。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：PBKDF2 迭代 20 万次、单次验证约 0.1 秒，登录毫无感觉；但每秒能算百亿个 SHA-256 的 GPU，现在每秒只能试约 5 万个候选——攻击成本被放大 20 万倍，这正是「故意慢」的含义。")],-1)),(r(),B(A,null,{default:e(()=>[l(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8A%84%E8%B5%B0%E5%93%88%E5%B8%8C%E5%BA%93%22%5D%20--%3E%20G%5B%22%E5%8F%96%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%E5%8F%A3%E4%BB%A4%20p%22%5D%0A%20%20G%20--%3E%20H%5B%22%E7%AE%97%20KDF(p%2C%20%E8%AF%A5%E7%94%A8%E6%88%B7%E7%9A%84%E7%9B%90)%22%5D%0A%20%20H%20--%3E%20CMP%5B%22%E4%B8%8E%E5%BA%93%E9%87%8C%E7%9A%84%E6%B4%BE%E7%94%9F%E5%80%BC%E6%AF%94%E5%AF%B9%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E5%8C%B9%E9%85%8D%22%7C%20G2%5B%22%E6%8D%A2%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%EF%BC%8C%E9%87%8D%E6%9D%A5%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%8C%B9%E9%85%8D%22%7C%20HIT%5B%22%E5%8F%A3%E4%BB%A4%E7%8C%9C%E4%B8%AD%22%5D%0A%20%20H%20--%3E%20COST%5B%22%E8%BF%AD%E4%BB%A3%20t%20%E6%AC%A1%EF%BC%9A%E5%90%9E%E5%90%90%E9%99%8D%20t%20%E5%80%8D%22%5D%0A%20%20COST%20--%3E%20PU%5B%22%E7%9B%90%E5%90%84%E4%B8%8D%E7%9B%B8%E5%90%8C%EF%BC%9A%E6%8D%A2%E7%94%A8%E6%88%B7%E5%B0%B1%E5%BE%97%E9%87%8D%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入生物特征模板当口令替代。网上如何证明「此刻是谁」且抗重放，下一课认证协议。</p><p>后课默认：口令存储用慢 KDF。交互认证是另一套消息。</p><p><span class="marginnote">常见误区：以为「把 MD5 换成 SHA-512 存口令就更安全」。摘要函数比的是快，越快对攻击者越有利——正确方向是换专用慢函数（Argon2、scrypt、bcrypt）并随硬件调参，而不是换更快的哈希。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>口令派生必须慢且加盐；会话派生要快。</li><li>抄库后的离线猜测靠代价挡住，不是靠保密算法名。</li><li>认证协议下一课。</li><li>出处：PKCS #5；Morris and Thompson；Anderson。</li></ul>',6))])}const _=n(D,[["render",p]]);export{u as __pageData,_ as default};
